package com.dat.ai_receptionist_web.controller.Catalog;
import com.dat.ai_receptionist_web.dto.*; import com.dat.ai_receptionist_web.dto.Catalog.TrainingPlanRequirementDTO; import com.dat.ai_receptionist_web.service.Catalog.TrainingPlanRequirementService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Pageable; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/training-plan-requirements") @RequiredArgsConstructor public class TrainingPlanRequirementController {private final TrainingPlanRequirementService service; @GetMapping @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_REQUIREMENT_READ.getCode())") public PageResponse<TrainingPlanRequirementDTO.SimpleResponse> list(@RequestParam(required=false) UUID trainingPlanId,Pageable p){return service.list(trainingPlanId,p);} @GetMapping("/{id}") @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_REQUIREMENT_READ.getCode())") public TrainingPlanRequirementDTO.Response get(@PathVariable UUID id){return service.get(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_REQUIREMENT_CREATE.getCode())") public TrainingPlanRequirementDTO.Response create(@Valid @RequestBody TrainingPlanRequirementDTO.CreateRequest r){return service.create(r);} @PutMapping("/{id}") @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_REQUIREMENT_UPDATE.getCode())") public TrainingPlanRequirementDTO.Response update(@PathVariable UUID id,@Valid @RequestBody TrainingPlanRequirementDTO.UpdateRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_REQUIREMENT_DELETE.getCode())") public void delete(@PathVariable UUID id){service.delete(id);} }
